components.css:
:host{--gs-bg:#080c13;--gs-panel:#101620;--gs-line:#303b50;--gs-muted:#b4bfd2;--gs-accent:#7846f7;--gs-ink:#ffffff;--gs-accent-bright:#a28aff;--gs-accent-soft:#d0bfff;--gs-selected:#241b48;--gs-input:#131c29;--gs-focus:#b8a4ff;font:14px "Segoe UI",system-ui,sans-serif;}
.gs-length-choice{display:flex;gap:4px;padding:4px;background:#0b111b;border:1px solid var(--gs-line);border-radius:8px}
.gs-length-choice button{flex:1;min-width:0;min-height:40px;padding:8px;color:#d0d8e8;background:transparent;border:1px solid transparent;border-radius:5px;font:inherit;cursor:pointer}
.gs-length-choice button[aria-pressed=true]{background:var(--gs-selected);border-color:var(--gs-accent-bright);color:#f6f0ff}
.gs-length-choice button:hover:not(:disabled){background:#352163;color:#fff}
.gs-length-choice button:focus-visible{outline:2px solid var(--gs-focus);outline-offset:2px}
.gs-length-choice button:disabled{opacity:.55;cursor:not-allowed}
